def is_lm(a, j):
    # j is a local minimum: strictly smaller than each of its neighbours
    # (first and last elements have only one neighbour)
    return And(
        0 <= j, j < N,
        If(j == 0, a[0] < a[1],
           If(j == N - 1, a[N - 1] < a[N - 2],
              And(a[j] < a[j - 1], a[j] < a[j + 1])))
    )

def post(a, r):
    k = Int('k')
    no_lm = ForAll([k], Implies(And(0 <= k, k < N), Not(is_lm(a, k))))
    last_lm = And(
        0 <= r, r < N,
        is_lm(a, r),
        ForAll([k], Implies(And(r < k, k < N), Not(is_lm(a, k))))
    )
    return Or(
        And(r == -1, no_lm),
        last_lm
    )
